import {ComplaintClassification,AINetworkSummary} from './AdminAIViews';
import {liveMode} from '../services/backendClient';

import { defaultPermissions, permissionLabels, Permission } from '../models/permissions';

'use client';

import { useState } from 'react';

import { useManagerViewModel } from '../viewmodels/useManagerViewModel';

import { useCampusStatusHistoryViewModel } from '../viewmodels/useCampusStatusHistoryViewModel';

import { useTestHistoryViewModel } from '../viewmodels/useTestHistoryViewModel';

import { Wifi, LayoutDashboard, MapPin, ClipboardList, Activity, Bell, Search, Download, Upload, ArrowUpRight, ShieldCheck, Users, Settings, CircleCheck, TriangleAlert, Clock, Plus, Play, X, ChevronRight, Building2, Radio, Check, SlidersHorizontal } from 'lucide-react';

import { Toaster } from '@/components/ui/sonner';

import { SidebarProvider, Sidebar, SidebarHeader, SidebarContent, SidebarFooter, SidebarMenu, SidebarMenuItem, SidebarMenuButton, SidebarTrigger, useSidebar } from '@/components/ui/sidebar';

import { Select, SelectTrigger, SelectContent, SelectItem, SelectValue } from '@/components/ui/select';

import { Dialog, DialogContent, DialogTitle, DialogDescription } from '@/components/ui/dialog';

import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';

import { Table, TableHeader, TableBody, TableRow, TableHead, TableCell } from '@/components/ui/table';

import { Progress } from '@/components/ui/progress';

import { Switch } from '@/components/ui/switch';

import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

