import { mapFilters, useMapViewModel } from '../viewmodels/useMapViewModel';

import { CoordinatePicker, OpenStreetMapView } from './OpenStreetMapView';

import { validCoordinates } from '../models/mapConfig';

import { CustomLocationEditor } from './CustomLocationEditor';

import { recordedTrend } from '../viewmodels/networkAnalytics';



const metric=(value:number)=>Number.isFinite(value)?Math.round(value*10)/10:'—';



const roles:Role[]=['Student','IT Support','Manager','Administrator'];

const categories=['Slow Internet','High Latency','Disconnections','Weak Signal','No Internet','Website / Service Unavailable','Other'];

const navIcons:Record<string,typeof Wifi>={Dashboard:LayoutDashboard,'Complaint Classification':ClipboardList,'AI Network Summary':Activity,Permissions:ShieldCheck,'System Reports':Activity,Connections:Wifi,'IT Support Activity':Users,'Reports & Analytics':Activity,'Recurring Problems':TriangleAlert,'Test Connection':Wifi,Locations:MapPin,'Submit Complaint':ClipboardList,'Test History':Activity,'My Complaints':ClipboardList,'All Test Results':Activity,'All Complaints':ClipboardList,'Poor Performance':TriangleAlert,'Maintenance Notes':Settings,'Support Queue':ClipboardList,'Campus Status':Radio,Analytics:Activity,Users:Users,Settings:Settings,Notifications:Bell};

const links:Record<Role,string[]>={Student:['Dashboard','Test Connection','Locations','Submit Complaint','Test History','My Complaints','Campus Status','Notifications'],'IT Support':['Dashboard','All Test Results','All Complaints','Poor Performance','Maintenance Notes','Locations','Campus Status','Notifications'],Manager:['Dashboard','Connections','IT Support Activity','Reports & Analytics','Recurring Problems','Locations','Campus Status','Notifications'],Administrator:['Dashboard','Locations','Users','Permissions','Complaint Classification','AI Network Summary','System Reports','Settings','Campus Status','Notifications']};

const date=(s:string)=>new Date(s).toLocaleString('en-GB',{timeZone:'Asia/Karachi',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});

function Pick({value,onChange,options,label,disabled=false,optionLabels}:{value:string;onChange:(v:string)=>void;options:string[];label:string;disabled?:boolean;optionLabels?:Record<string,string>}) {return <Select value={value} onValueChange={onChange} disabled={disabled}><SelectTrigger aria-label={label} className="picker"><SelectValue /></SelectTrigger><SelectContent>{options.map(x=><SelectItem key={x} value={x}>{optionLabels?.[x]||x}</SelectItem>)}</SelectContent></Select>;}

function Badge({text}:{text:string}){return <span className={`badge ${text.toLowerCase().replaceAll(' ','-')}`}>{text}</span>;}

function Panel({title,subtitle,action,children,className=''}:{title:string;subtitle?:string;action?:React.ReactNode;children:React.ReactNode;className?:string}){return <section className={`panel ${className}`}><div className="panel-heading"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</section>;}

function Stat({title,value,note,icon:Icon,tone='green'}:{title:string;value:string|number;note:string;icon:typeof Wifi;tone?:string}){return <div className="stat"><div className={`stat-icon ${tone}`}><Icon size={21}/></div><div><p>{title}</p><strong>{value}</strong><small>{note}</small></div></div>;}

function Navigation({vm}:{vm:CampusVM}){const {setOpenMobile}=useSidebar();return <Sidebar className="campus-sidebar"><SidebarHeader><div className="brand campus-logo-brand"><img src="/branding/campusnet-logo.png" alt="CampusNet"/></div></SidebarHeader><SidebarContent><p className="nav-caption">WORKSPACE</p><SidebarMenu>{links[vm.role].filter(label=>{const permission=({'All Test Results':'tests','All Complaints':'complaints','Maintenance Notes':'maintenance','Poor Performance':'maintenance','Reports & Analytics':'reports','IT Support Activity':'reports','Recurring Problems':'reports'} as Record<string,Permission>)[label];return !permission||vm.can(permission);}).map(label=>{const Icon=navIcons[label];return <SidebarMenuItem key={label}><SidebarMenuButton isActive={vm.page===label} onClick={()=>{if(label==='System Reports'){vm.setBuilding('All buildings');vm.setQuery('');}vm.setPage(label);setOpenMobile(false);}} className="nav-item"><Icon size={18}/><span>{label}</span>{label==='Support Queue'&&<b className="nav-count">{vm.data.complaints.filter(c=>c.status!=='Resolved').length}</b>}</SidebarMenuButton></SidebarMenuItem>;})}</SidebarMenu><div className="sidebar-help"><ShieldCheck size={22}/><strong>A better connected campus</strong><p>Measure. Report. Resolve.</p></div></SidebarContent><SidebarFooter><div className="profile"><span className="avatar">{vm.role==='Student'?'AJ':vm.role==='IT Support'?'SK':vm.role==='Manager'?'OA':'AA'}</span><div><strong>{liveMode?(vm.data as any).user?.name:vm.role==='Student'?'Alex Johnson':vm.role==='IT Support'?'Sarah Khan':vm.role==='Manager'?'Omar Ali':'Ayesha Ahmed'}</strong><small>{vm.role}</small></div></div></SidebarFooter></Sidebar>;}



export function CampusApp({session,onSignOut}:{session?:{name:string;email:string};onSignOut?:()=>void}){const vm=useCampusViewModel();useCampusTools(vm);const [modal,setModal]=useState('');const [detail,setDetail]=useState<Complaint|null>(null);const titles:Record<Role,string>={Student:'Your campus, connected.', 'IT Support':'Keep the campus connected.',Manager:'A clearer view of campus health.',Administrator:'Your campus control center.'};

return <SidebarProvider><Navigation vm={vm}/><main className="workspace"><header className="topbar"><div className="crumb"><SidebarTrigger className="mobile-menu"/><span>Workspace</span><ChevronRight size={14}/><strong>{vm.role}</strong></div><div className="top-actions">{onSignOut&&<button className="secondary small" onClick={onSignOut}>Sign out</button>}<span className="demo-label">{session?.name||'Demo workspace'}</span><button className="icon-btn" aria-label="Open notifications" onClick={()=>vm.setPage('Notifications')}><Bell size={19}/>{vm.unreadAlerts>0&&<span className="notification-dot"/>}</button><Pick label="Preview dashboard role" disabled={liveMode} value={vm.role} onChange={v=>vm.switchRole(v as Role)} options={roles}/></div></header><div className="page"><div className="page-heading"><div><div className="eyebrow">SMART CAMPUS / {vm.page.toUpperCase()}</div><h1>{vm.page==='Dashboard'?titles[vm.role]:vm.page}</h1><p>{vm.page==='Dashboard'?'Monitor Wi-Fi health, catch issues early, and keep work moving.':'Everything you need to understand and improve your connection.'}</p></div><div className="heading-actions">{vm.role==='Student'?<button className="primary" onClick={()=>vm.setPage('Test Connection')}><Wifi size={17}/>Run Wi-Fi test</button>:<button className="secondary" onClick={vm.exportReport}><Download size={17}/>Export report</button>}</div></div>

<div className="demo-banner"><Radio size={16}/><span>{liveMode?'Campus data · Connected to the authenticated campus server.':'Sample campus data · Changes are saved on this device. Network tests are simulated.'}</span></div>

{!['Test Connection','Submit Complaint','Settings','Users','Notifications','Test History','All Test Results','Maintenance Notes','Permissions','System Reports','Complaint Classification','AI Network Summary'].includes(vm.page)&&<div className="filterbar"><div className="filter-left"><SlidersHorizontal size={17}/><Pick value={vm.building} onChange={vm.setBuilding} options={['All buildings',...Array.from(new Set(vm.data.locations.map(l=>l.building)))]} label="Filter by building"/><span className="filter-count">{vm.locations.length} locations</span></div><label className="search"><Search size={17}/><input aria-label="Search locations" placeholder="Search locations…" value={vm.query} onChange={e=>vm.setQuery(e.target.value)}/></label></div>}

{vm.page==='Dashboard'&&<Dashboard vm={vm} onComplaint={()=>setModal('complaint')} onDetail={setDetail}/>}

{vm.page==='Test Connection'&&<SpeedTest vm={vm}/>}

{vm.page==='Submit Complaint'&&<Panel title="Tell us what happened" subtitle="Include the location and details so IT can investigate."><ComplaintForm vm={vm} onDone={()=>vm.setPage('My Complaints')}/></Panel>}

{(vm.page==='My Complaints'||vm.page==='Support Queue'||vm.page==='All Complaints')&&<ComplaintList vm={vm} onDetail={setDetail} onNew={()=>setModal('complaint')}/>}

{vm.page==='Locations'&&<Locations vm={vm} onAdd={()=>setModal('location')}/>}

{vm.page==='Poor Performance'&&<><Panel title="Poor performance locations" subtitle="Measured scores below 50, lowest first. Unknown locations are excluded."><PriorityList vm={{...vm,locations:vm.locations.filter(l=>l.tests&&l.score<50)}}/></Panel><div className="section-gap"><MaintenanceNotes vm={vm}/></div></>}{vm.page==='Maintenance Notes'&&<MaintenanceNotes vm={vm}/>}{(vm.page==='Campus Status'||vm.page==='Connections')&&<CampusStatus vm={vm}/>}

{['IT Support Activity','Reports & Analytics','Recurring Problems'].includes(vm.page)&&<ManagerTools vm={vm}/>} {vm.page==='Analytics'&&<><Analytics vm={vm}/><div className="section-gap"><Locations vm={vm} onAdd={()=>{}}/></div></>}

{vm.page==='Users'&&<UserManagement vm={vm}/>}

{vm.page==='Permissions'&&<PermissionSettings vm={vm}/>} {vm.page==='System Reports'&&<ManagerTools vm={{...vm,page:'Reports & Analytics',locations:vm.data.locations}}/>} {vm.page==='Settings'&&<SettingsView vm={vm}/>}

{(vm.page==='Test History'||vm.page==='All Test Results')&&<TestHistory vm={vm}/>}

{vm.role==='Administrator'&&vm.page==='Complaint Classification'&&<ComplaintClassification vm={vm}/>}
{vm.role==='Administrator'&&vm.page==='AI Network Summary'&&<AINetworkSummary vm={vm}/>}
{vm.page==='Notifications'&&<Notifications vm={vm}/>}<footer className="page-footer"><span><Wifi size={14}/> Smart Campus</span><span>Campus time: Asia/Karachi</span></footer></div></main>

<Dialog open={modal!==''} onOpenChange={open=>!open&&setModal('')}><DialogContent className="campus-dialog"><DialogTitle>{modal==='location'?'Add a campus location':'Submit a complaint'}</DialogTitle><DialogDescription>{modal==='location'?'Create a monitoring location. It starts with unknown health.':'Help IT understand where your connection needs attention.'}</DialogDescription>{modal==='location'?<LocationForm vm={vm} onDone={()=>setModal('')}/>:<ComplaintForm vm={vm} onDone={()=>setModal('')}/>}</DialogContent></Dialog>

<Dialog open={!!detail} onOpenChange={open=>!open&&setDetail(null)}><DialogContent className="campus-dialog"><DialogTitle>Complaint {detail?.id}</DialogTitle><DialogDescription>Issue details and support history.</DialogDescription>{detail&&<ComplaintDetail key={detail.id} complaint={vm.data.complaints.find(c=>c.id===detail.id)||detail} vm={vm} onDone={()=>setDetail(null)}/>}</DialogContent></Dialog><Toaster richColors closeButton position="bottom-right"/></SidebarProvider>;}



function Dashboard({vm,onComplaint,onDetail}:{vm:CampusVM;onComplaint:()=>void;onDetail:(c:Complaint)=>void}){const measured=vm.locations.filter(l=>l.tests>0);const good=measured.filter(l=>l.score>=vm.data.thresholds.good).length;const fair=measured.filter(l=>l.score>=50&&l.score<vm.data.thresholds.good).length;const poor=measured.filter(l=>l.score<50).length;const open=vm.complaints.filter(c=>c.status!=='Resolved').length;

return <><div className="stats-grid">{vm.role==='Administrator'?<><Stat title="Campus locations" value={vm.locations.length} note="Configured monitoring areas" icon={MapPin}/><Stat title="Active users" value={vm.data.users.filter(u=>u.active).length} note="Across four campus roles" icon={Users} tone="blue"/><Stat title="Needs attention" value={poor} note="Locations below fair health" icon={TriangleAlert} tone="red"/><Stat title="Open complaints" value={open} note="Awaiting verified resolution" icon={ClipboardList} tone="amber"/></>:vm.role==='IT Support'?<><Stat title="Open complaints" value={open} note="In the selected buildings" icon={ClipboardList} tone="red"/><Stat title="In progress" value={vm.complaints.filter(c=>c.status==='In Progress').length} note="Investigations underway" icon={Activity} tone="blue"/><Stat title="Poor locations" value={poor} note="Prioritize investigation" icon={TriangleAlert} tone="amber"/><Stat title="Resolved complaints" value={vm.complaints.filter(c=>c.status==='Resolved').length} note="Saved campus reports" icon={CircleCheck}/></>:<><Stat title="Healthy locations" value={good} note={`${measured.length?Math.round(good/measured.length*100):0}% of measured locations`} icon={ShieldCheck}/><Stat title="Fair locations" value={fair} note="Some room for improvement" icon={Wifi} tone="amber"/><Stat title="Poor locations" value={poor} note="Require IT attention" icon={TriangleAlert} tone="red"/><Stat title="Open complaints" value={open} note={vm.role==='Student'?'Your unresolved reports':'Across selected buildings'} icon={ClipboardList} tone="blue"/></>}</div>

{vm.role==='Student'&&<div className="connection-callout"><div className="callout-symbol"><Wifi size={31}/></div><div><span className="eyebrow">CHECK YOUR CONNECTION</span><h2>How’s your Wi-Fi doing?</h2><p>Get a connection snapshot and share issues with campus IT.</p></div><button className="primary" onClick={()=>vm.setPage('Test Connection')}><Play size={16}/>Start a test</button></div>}

{vm.role==='Manager'?<><Analytics vm={vm}/><div className="section-gap"><CampusMap vm={vm}/></div></>:<div className="dashboard-grid"><CampusMap vm={vm}/>{vm.role==='Student'?<Panel title="Recent activity" action={<button className="text-btn" onClick={()=>vm.setPage('My Complaints')}>View all</button>}><ActivityFeed vm={vm}/></Panel>:vm.role==='IT Support'?<Panel title="Priority attention" subtitle="Low scores with unresolved reports"><PriorityList vm={vm}/></Panel>:<Panel title="Configuration overview" subtitle="Keep your monitoring settings consistent"><div className="config-row"><div className="stat-icon blue"><Users size={19}/></div><div><strong>User access</strong><p>{vm.data.users.filter(u=>u.active).length} active accounts</p></div><button className="text-btn" onClick={()=>vm.setPage('Users')}>Manage</button></div><div className="config-row"><div className="stat-icon green"><Settings size={19}/></div><div><strong>Health thresholds</strong><p>Good ≥ {vm.data.thresholds.good} · Excellent ≥ {vm.data.thresholds.excellent}</p></div><button className="text-btn" onClick={()=>vm.setPage('Settings')}>Edit</button></div><div className="config-row"><div className="stat-icon amber"><MapPin size={19}/></div><div><strong>Campus locations</strong><p>{vm.data.locations.length} configured areas</p></div><button className="text-btn" onClick={()=>vm.setPage('Locations')}>View</button></div><div className="config-notice"><ShieldCheck size={18}/><p>Account access is verified by the campus server.</p></div></Panel>}</div>}

<div className="section-gap">{vm.role==='Student'&&<TestHistory vm={vm} compact/>}</div><div className="section-gap">{vm.role==='Administrator'?<UserManagement vm={vm}/>:<ComplaintList vm={vm} onDetail={onDetail} onNew={onComplaint} compact/>}</div></>;}



function CampusMap({vm}:{vm:CampusVM}){const model=useMapViewModel(vm);const l=model.selected;return <Panel title="Campus map overview" subtitle="Explore location health on OpenStreetMap" action={<Pick value={model.healthFilter} onChange={model.setHealthFilter} options={mapFilters} label="Map health filter"/>}><OpenStreetMapView model={model}/>{l&&<div className="map-detail"><div><strong>{l.building} · {l.name}</strong><p>{l.floor} · {l.tests} sample tests · {l.complaintCount} unresolved reports</p></div><Badge text={l.status}/></div>}<div className="map-legend"><span><i className="green"/>Healthy</span><span><i className="amber"/>Fair</span><span><i className="red"/>Poor</span><span><i className="gray"/>Unknown</span></div></Panel>;}

function ActivityFeed({vm}:{vm:CampusVM}){return <div className="activity-feed">{vm.data.tests.slice(0,1).map(t=><div className="activity-item" key={t.id}><span className="small-icon green"><Check size={17}/></span><div><strong>Connection test recorded</strong><p>{vm.data.locations.find(l=>l.id===t.locationId)?.name}</p><small>{date(t.testedAt)}</small></div></div>)}{vm.complaints.slice(0,4).map(c=><button className="activity-item" key={c.id} onClick={()=>vm.setPage('My Complaints')}><span className={`small-icon ${c.status==='Resolved'?'green':'red'}`}><ClipboardList size={16}/></span><div><strong>{c.status==='Resolved'?'Issue resolved':'Complaint '+c.status.toLowerCase()}</strong><p>{vm.data.locations.find(l=>l.id===c.locationId)?.building} · {c.category}</p><small>{date(c.createdAt)}</small></div><ChevronRight size={15}/></button>)}{!vm.complaints.length&&<p className="empty">No activity in this selection.</p>}</div>;}

function PriorityList({vm}:{vm:CampusVM}){return <div className="priority-list">{vm.locations.filter(l=>l.tests&&l.score<75).sort((a,b)=>a.score-b.score).map(l=><button key={l.id} onClick={()=>{vm.setBuilding(l.building);vm.setPage('All Complaints');}}><span className="small-icon red"><TriangleAlert size={18}/></span><div><strong>{l.building} · {l.name}</strong><p>{l.ping} ms RTT · {l.download} Mbps download</p></div><b>{l.score}<small>/100</small></b></button>)}{!vm.locations.some(l=>l.tests&&l.score<75)&&<p className="empty">No locations require attention in this selection.</p>}<div className="config-notice"><Clock size={17}/><p>Verify recovery before resolving an issue.</p></div></div>;}



function ComplaintList({vm,onDetail,onNew,compact=false}:{vm:CampusVM;onDetail:(c:Complaint)=>void;onNew:()=>void;compact?:boolean}){const [tab,setTab]=useState('All');const list=vm.complaints.filter(c=>tab==='All'||c.status===tab);return <Panel title={vm.role==='Student'?'My complaints':'All complaints'} subtitle={vm.role==='Student'?'Follow the progress of your reported issues.':'Review reports and move investigations forward.'} action={vm.role==='Student'?<button className="secondary small" onClick={onNew}><Plus size={15}/>New complaint</button>:<span className="muted">{list.length} reports</span>}><Tabs value={tab} onValueChange={setTab}><TabsList className="status-tabs">{['All','Open','Assigned','In Progress','Resolved'].map(s=><TabsTrigger value={s} key={s}>{s}</TabsTrigger>)}</TabsList></Tabs><div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Issue</TableHead><TableHead>Location</TableHead><TableHead>Status</TableHead><TableHead>{vm.role==='Student'?'Reported':'Assigned to'}</TableHead><TableHead className="right">Action</TableHead></TableRow></TableHeader><TableBody>{list.slice(0,compact?4:undefined).map(c=>{const l=vm.data.locations.find(l=>l.id===c.locationId);return <TableRow key={c.id}><TableCell><div className="issue-cell"><span className={`small-icon ${c.status==='Resolved'?'green':c.category==='No Internet'?'red':'amber'}`}><Wifi size={17}/></span><div><strong>{c.category}</strong><small>#{c.id}</small></div></div></TableCell><TableCell><strong>{l?.building}</strong><small>{l?.name}</small></TableCell><TableCell><Badge text={c.status}/></TableCell><TableCell>{vm.role==='Student'?date(c.createdAt):c.assignee}</TableCell><TableCell className="right"><button className="outline-link" onClick={()=>onDetail(c)}>{vm.role==='IT Support'?'Investigate':'View'}</button></TableCell></TableRow>;})}</TableBody></Table></div>{!list.length&&<p className="empty">No complaints match this filter.</p>}</Panel>;}

function ComplaintForm({vm,onDone}:{vm:CampusVM;onDone:()=>void}){const [category,setCategory]=useState('Slow Internet');const [description,setDescription]=useState('');const [loc,setLoc]=useState(vm.locationId);const [include,setInclude]=useState(true);const [addingLocation,setAddingLocation]=useState(false);const selected=vm.data.locations.find(l=>l.id===loc);const complaintMap=useMapViewModel({...vm,locations:vm.data.locations,locationId:loc,setLocationId:setLoc});return <form className="form" onSubmit={async e=>{e.preventDefault();if(await vm.submitComplaint(category,description,loc,include))onDone();}}><label>Location<Pick label="Complaint location" value={loc} onChange={value=>{if(value)setLoc(value);}} options={vm.data.locations.map(l=>l.id)} optionLabels={Object.fromEntries(vm.data.locations.map(l=>[l.id,`${l.building} · ${l.name}`]))}/><small>{selected?.building} · {selected?.floor} · {selected?.name}</small></label><div className="complaint-location-map"><p>Click a campus pin to select where the issue happened.</p><OpenStreetMapView model={complaintMap}/><div className="complaint-selected-location" role="status"><MapPin size={18}/><div><strong>Selected: {selected?.building} · {selected?.name}</strong><small>{selected?.floor} · {selected?.id}</small></div></div></div><button type="button" className="secondary" onClick={()=>setAddingLocation(true)} disabled={addingLocation}><Plus size={16}/>Add custom location</button>{addingLocation&&<CustomLocationEditor vm={vm} onSaved={id=>{setLoc(id);setAddingLocation(false);}} onCancel={()=>setAddingLocation(false)}/>}<label>Issue type</label><div className="category-grid">{categories.map(c=><button key={c} type="button" aria-pressed={c===category} className={c===category?'selected':''} onClick={()=>setCategory(c)}><Wifi size={20}/><span>{c}</span></button>)}</div><label>Description<textarea required minLength={10} maxLength={500} placeholder="Describe what happened, when it started, and who is affected…" value={description} onChange={e=>setDescription(e.target.value)}/><small className="right">{description.length}/500</small></label><div className="switch-row"><Switch id="attach-test" checked={include} onCheckedChange={setInclude} disabled={vm.running}/><label htmlFor="attach-test"><strong>Run and attach latest test</strong><small>{liveMode?'Run a fresh connection test and attach its result before sending.':'Attach the saved result for this location.'}</small></label></div><div className="form-actions"><button type="button" className="secondary" onClick={onDone}>Cancel</button><button className="primary" type="submit" disabled={vm.running}>{vm.running?'Testing connection…':'Submit complaint'}</button></div></form>;}

function ComplaintDetail({complaint:c,vm,onDone}:{complaint:Complaint;vm:CampusVM;onDone:()=>void}){const [status,setStatus]=useState(c.status);const [assignee,setAssignee]=useState(liveMode?(c.assigneeId||'Unassigned'):c.assignee);const [note,setNote]=useState('');const l=vm.data.locations.find(l=>l.id===c.locationId);const canEdit=vm.role==='IT Support'&&vm.can('complaints');return <div className="form"><div className="detail-top"><Badge text={c.status}/><span>{date(c.createdAt)}</span></div><h3>{c.category}</h3><p>{l?.building} · {l?.name}</p><p className="description-box">{c.description}</p>{c.attachedTest&&<div className="description-box"><strong>Attached connection test</strong><p>Download: {metric(c.attachedTest.download)} Mbps · Upload: {metric(c.attachedTest.upload)} Mbps · Latency: {metric(c.attachedTest.ping)} ms</p><small>{date(c.attachedTest.testedAt)}</small></div>}<h3>Support history</h3>{c.notes.length?c.notes.map((n,i)=><p className="history-note" key={i}><Clock size={14}/>{n}</p>):<p className="muted">No updates yet. Your report is awaiting review.</p>}{canEdit&&<><div className="form-grid"><label>Status<Pick value={status} onChange={s=>setStatus(s as Status)} options={['Open','Assigned','In Progress','Resolved']} label="Complaint status"/></label><label>Assignee<Pick value={assignee} onChange={setAssignee} options={liveMode?['Unassigned',...vm.data.users.filter(u=>u.active&&['IT Support','Manager','Administrator'].includes(u.role)).map(u=>u.id)]:['Unassigned','Sarah Khan','Omar Ali']} optionLabels={liveMode?Object.fromEntries(vm.data.users.map(u=>[u.id,u.name])):undefined} label="Assigned staff"/></label></div><label>{status==='Resolved'?'Resolution note (optional)':'Investigation note'}<textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Record what you checked and what changed…"/></label><button className="primary" disabled={status!=='Open'&&status!=='Resolved'&&assignee==='Unassigned'} onClick={async()=>{if(await vm.updateComplaint(c.id,status,assignee,note))onDone();}}>Save update</button></>}</div>;}



function SpeedTest({vm}:{vm:CampusVM}){const t=vm.lastTest;const l=vm.location;if(!l)return <Panel title="Connection test"><p className="empty">No campus location is available. Add a custom location or contact your administrator.</p></Panel>;return <div className="test-layout"><Panel title="Run a Wi-Fi test" subtitle="Select where you are, then check your connection."><div className="stepper"><span className="active">1 · Location</span><i/><span className={vm.running?'active':''}>2 · Test</span><i/><span className={t?'active':''}>3 · Results</span></div><div className="form"><label>Campus location<Pick value={vm.locationId} onChange={vm.setLocationId} options={vm.data.locations.map(l=>l.id)} label="Test location" optionLabels={Object.fromEntries(vm.data.locations.map(l=>[l.id,l.building+' · '+l.name]))} disabled={vm.running}/></label><div className="location-summary"><MapPin size={25}/><div><strong>{l.building} · {l.name}</strong><p>{l.floor} · {l.id}</p></div><Badge text={l.tests?health(l.score,vm.data.thresholds):'Unknown'}/></div><div className="test-dial" style={{background:`conic-gradient(var(--coral) ${vm.running?vm.progress:t?100:0}%, #e8edf3 0)`}}><div><Wifi size={29}/><span>{vm.running?'Testing…':t?'Complete':'Ready to test'}</span><strong>{vm.running?`${vm.progress}%`:t?String(t.score??'—'):'—'}</strong><small>{t?'health score':(liveMode?'HTTP measurement':'simulated demo')}</small></div></div>{vm.running&&<Progress aria-label="Test progress" value={vm.progress}/>}<button disabled={liveMode&&!l} className={vm.running?'secondary':'primary'} onClick={vm.running?vm.cancelTest:vm.runTest}>{vm.running?<><X size={17}/>Cancel test</>:<><Play size={17}/>{t?'Run again':(liveMode?'Start test':'Start demo test')}</>}</button></div></Panel><Panel title="Connection results" subtitle={liveMode?'Measures your device’s internet download, upload and latency against Cloudflare.':'Browser measurement endpoints are not connected yet.'}>{t?<><div className="result-banner"><CircleCheck size={26}/><div><strong>{health(t.score,vm.data.thresholds)} connection</strong><p>{liveMode?'Measured result':'Simulated result'} · {date(t.testedAt)}</p></div></div><div className="metric-grid"><div><Activity/><small>Application RTT</small><strong>{metric(t.ping)}<em>ms</em></strong></div><div><Download/><small>Download</small><strong>{metric(t.download)}<em>Mbps</em></strong></div><div><Upload/><small>Upload</small><strong>{metric(t.upload)}<em>Mbps</em></strong></div><div><ShieldCheck/><small>Packet loss</small><strong>—</strong><small>Not measured</small></div></div><div className="config-notice"><Wifi size={18}/><p>{t.score>=75?'This sample indicates healthy speed and latency.':t.score>=50?'This sample indicates reduced performance.':'This sample indicates low speed or high latency.'} Scores are calculated by the campus server.</p></div><button className="secondary full" onClick={()=>vm.setPage('Submit Complaint')}><TriangleAlert size={17}/>Report a problem</button></>:<div className="test-empty"><Activity size={44}/><h3>Your results will appear here</h3><p>Run a test to measure the connection at your selected location.</p></div>}</Panel></div>;}

function TestHistory({vm,compact=false}:{vm:CampusVM;compact?:boolean}){const model=useTestHistoryViewModel(vm);const rows=compact?model.tests.slice(0,3):model.tests;return <Panel title={compact?'Recent test history':vm.role==='IT Support'?'All network test results':'Your test history'} subtitle="Saved connection tests · newest first." action={compact?<button className="text-btn" onClick={()=>vm.setPage('Test History')}>View test history</button>:<span className="muted">{model.tests.length} tests</span>}>{!compact&&<div className="filterbar"><Pick label="Filter test history by location" value={model.locationId} onChange={model.setLocationId} options={['All locations',...vm.data.locations.map(l=>l.id)]} optionLabels={Object.fromEntries(vm.data.locations.map(l=>[l.id,l.building+' · '+l.name]))}/></div>}<div className="table-scroll"><Table><TableHeader><TableRow>{['Location','Download','Upload','RTT','Health','Time','Action'].map(s=><TableHead key={s}>{s}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map(t=>{const l=vm.data.locations.find(l=>l.id===t.locationId);return <TableRow key={t.id}><TableCell><strong>{l?.building||'Unavailable location'}</strong><small>{l?.name}</small></TableCell><TableCell>{metric(t.download)} Mbps</TableCell><TableCell>{metric(t.upload)} Mbps</TableCell><TableCell>{metric(t.ping)} ms</TableCell><TableCell><Badge text={health(t.score,vm.data.thresholds)}/><small>{t.score??'—'}/100 · {liveMode?'Measured':'Demo'}</small></TableCell><TableCell>{date(t.testedAt)}</TableCell><TableCell><button className="outline-link" onClick={()=>{if(vm.role==='IT Support'){vm.setBuilding('All buildings');vm.setQuery('');vm.setLocationId(t.locationId);vm.setPage('Campus Status');}else model.runAgain(t.locationId);}}>{vm.role==='IT Support'?'View location':'Test again'}</button></TableCell></TableRow>;})}</TableBody></Table></div>{!rows.length&&<div className="empty"><p>{vm.data.tests.length?'No tests at this location yet.':'No tests yet. Complete a connection test to start your history.'}</p><button className="primary" onClick={()=>vm.setPage('Test Connection')}>Run a connection test</button></div>}</Panel>;}



function Locations({vm,onAdd}:{vm:CampusVM;onAdd:()=>void}){const [editing,setEditing]=useState<Location|null>(null);const [addingCustom,setAddingCustom]=useState(false);return <><CampusMap vm={vm}/><div className="section-gap"><Panel title="Location health" subtitle="Compare connection quality across campus areas." action={vm.role==='Administrator'?<button className="primary small" onClick={onAdd}><Plus size={15}/>Add location</button>:<button className="secondary small" onClick={()=>setAddingCustom(true)}><Plus size={15}/>Add custom location</button>}><div className="table-scroll"><Table><TableHeader><TableRow>{['Location','Health score','Download','Upload','RTT','Samples','Map position'].map(s=><TableHead key={s}>{s}</TableHead>)}</TableRow></TableHeader><TableBody>{vm.locations.map(l=><TableRow key={l.id}><TableCell><strong>{l.building} · {l.name}</strong><small>{l.floor}</small></TableCell><TableCell><div className="score-cell"><b>{l.tests?l.score:'—'}</b><Badge text={l.tests?health(l.score,vm.data.thresholds):'Unknown'}/></div></TableCell><TableCell>{l.tests?`${l.download} Mbps`:'—'}</TableCell><TableCell>{l.tests?`${l.upload} Mbps`:'—'}</TableCell><TableCell>{l.tests?`${l.ping} ms`:'—'}</TableCell><TableCell>{l.tests}</TableCell><TableCell>{vm.role==='Administrator'?<button className="outline-link" onClick={()=>setEditing(l)}>{validCoordinates(l.latitude,l.longitude)?'Edit location':'Name and place pin'}</button>:<span className="muted">{validCoordinates(l.latitude,l.longitude)?l.coordinateSource==='demo'?'Demo pin':'Positioned':'Not placed'}</span>}</TableCell></TableRow>)}</TableBody></Table></div>{!vm.locations.length&&<p className="empty">No locations match your search.</p>}</Panel></div><Dialog open={!!editing} onOpenChange={open=>!open&&setEditing(null)}><DialogContent className="campus-dialog"><DialogTitle>Edit campus location</DialogTitle><DialogDescription>Update the name and details, then click the map to move its pin.</DialogDescription>{editing&&<CoordinateForm key={editing.id} location={editing} vm={vm} onDone={()=>setEditing(null)}/>}</DialogContent></Dialog><Dialog open={addingCustom} onOpenChange={setAddingCustom}><DialogContent className="campus-dialog"><DialogTitle>Add custom location</DialogTitle><DialogDescription>Name a location and place its pin on the campus map.</DialogDescription><CustomLocationEditor vm={vm} onSaved={id=>{vm.setLocationId(id);vm.setBuilding('All buildings');vm.setQuery('');setAddingCustom(false);}} onCancel={()=>setAddingCustom(false)}/></DialogContent></Dialog></>;}

function LocationForm({vm,onDone}:{vm:CampusVM;onDone:()=>void}){const [name,setName]=useState('');const [building,setBuilding]=useState('');const [floor,setFloor]=useState('');const [lat,setLat]=useState('');const [lng,setLng]=useState('');const point=lat!==''&&lng!==''&&validCoordinates(Number(lat),Number(lng))?[Number(lat),Number(lng)] as [number,number]:undefined;return <form className="form" onSubmit={async e=>{e.preventDefault();if(await vm.addLocation(name,building,floor,lat===''?undefined:Number(lat),lng===''?undefined:Number(lng)))onDone();}}><label>Location name<input required maxLength={80} value={name} onChange={e=>setName(e.target.value)} placeholder="Computer Lab 2"/></label><label>Building<input required maxLength={80} value={building} onChange={e=>setBuilding(e.target.value)} placeholder="Science"/></label><label>Floor<input maxLength={40} value={floor} onChange={e=>setFloor(e.target.value)} placeholder="Floor 2"/></label><CoordinatePicker point={point} onPick={(a,b)=>{setLat(a.toFixed(6));setLng(b.toFixed(6));}}/><CoordinateFields lat={lat} lng={lng} setLat={setLat} setLng={setLng}/><small>Coordinates are optional. Unplaced locations stay in the list without a map pin.</small><button className="primary">Add location</button></form>;}

function CoordinateFields({lat,lng,setLat,setLng}:{lat:string;lng:string;setLat:(s:string)=>void;setLng:(s:string)=>void}){return <div className="form-grid"><label>Latitude<input type="number" step="any" min={-90} max={90} value={lat} onChange={e=>setLat(e.target.value)} placeholder="25.406460"/></label><label>Longitude<input type="number" step="any" min={-180} max={180} value={lng} onChange={e=>setLng(e.target.value)} placeholder="68.260320"/></label></div>;}

function CoordinateForm({location:l,vm,onDone}:{location:Location;vm:CampusVM;onDone:()=>void}){const [name,setName]=useState(l.name);const [building,setBuilding]=useState(l.building);const [floor,setFloor]=useState(l.floor);const [lat,setLat]=useState(l.latitude?.toString()||'');const [lng,setLng]=useState(l.longitude?.toString()||'');const point=lat!==''&&lng!==''&&validCoordinates(Number(lat),Number(lng))?[Number(lat),Number(lng)] as [number,number]:undefined;return <form className="form" onSubmit={async e=>{e.preventDefault();if(point&&await vm.updateLocation(l.id,name,building,floor,point[0],point[1]))onDone();}}><label>Location name<input aria-label="Edit location name" required minLength={2} maxLength={80} value={name} onChange={e=>setName(e.target.value)}/></label><div className="form-grid"><label>Building<input aria-label="Edit location building" required maxLength={80} value={building} onChange={e=>setBuilding(e.target.value)}/></label><label>Floor<input aria-label="Edit location floor" maxLength={40} value={floor} onChange={e=>setFloor(e.target.value)}/></label></div><CoordinatePicker point={point} onPick={(a,b)=>{setLat(a.toFixed(6));setLng(b.toFixed(6));}}/><CoordinateFields lat={lat} lng={lng} setLat={setLat} setLng={setLng}/><small>Existing tests, complaints, and maintenance notes remain linked to this location.</small><button className="primary" disabled={!point||name.trim().length<2||!building.trim()}>Save location changes</button></form>;}

function CampusStatus({vm}:{vm:CampusVM}){const model=useCampusStatusHistoryViewModel(vm);return <><Tabs value={model.view} onValueChange={model.setView}><TabsList className="status-tabs"><TabsTrigger value="Current status">Current status</TabsTrigger><TabsTrigger value="Previous status">Previous status</TabsTrigger></TabsList></Tabs>{model.view==='Previous status'?<Panel title="Previous network status" subtitle="Saved observations across campus locations. Dates use campus time (Asia/Karachi)."><div className="form-grid form"><label>From date<input aria-label="Status history from date" type="date" value={model.from} onChange={e=>model.setFrom(e.target.value)}/></label><label>To date<input aria-label="Status history to date" type="date" value={model.to} onChange={e=>model.setTo(e.target.value)}/></label></div>{model.invalidRange&&<p role="alert">From date must be on or before To date.</p>}<div className="table-scroll"><Table><TableHeader><TableRow>{['Recorded at','Location','Previous health','Current health','Download','Upload','Latency'].map(title=><TableHead key={title}>{title}</TableHead>)}</TableRow></TableHeader><TableBody>{model.records.map((t:any)=>{const l=vm.data.locations.find(l=>l.id===t.locationId);return <TableRow key={t.id}><TableCell>{date(t.testedAt)}<small>Recorded observation</small></TableCell><TableCell><strong>{l?.building}</strong><small>{l?.name}</small></TableCell><TableCell><Badge text={health(t.score,vm.data.thresholds)}/><small>{t.score??'—'}/100</small></TableCell><TableCell><Badge text={l?.tests?health(l.score,vm.data.thresholds):'Unknown'}/></TableCell><TableCell>{metric(t.download)} Mbps</TableCell><TableCell>{metric(t.upload)} Mbps</TableCell><TableCell>{metric(t.ping)} ms</TableCell></TableRow>;})}</TableBody></Table></div>{!model.records.length&&!model.invalidRange&&<div className="empty"><p>No saved observations match these locations and dates.</p><p>Complete a connection test to begin recording network status.</p></div>}<small className="muted">Historical labels use the current health thresholds. These observations do not confirm an outage.</small></Panel>:<><CampusMap vm={vm}/><div className="section-gap"/><div className="status-overview"><Radio size={30}/><div><h2>{vm.locations.some(l=>l.tests&&l.score<50)?'Some areas need attention':vm.locations.some(l=>l.tests)?'Measured areas are healthy':'Awaiting network measurements'}</h2><p>Recent health observations. An outage must be confirmed by IT.</p></div></div><div className="location-cards">{vm.locations.map(l=><div className="panel location-card" key={l.id}><div className="location-card-top"><Building2 size={25}/><Badge text={l.tests?health(l.score,vm.data.thresholds):'Unknown'}/></div><h3>{l.building}</h3><p>{l.name} · {l.floor}</p><div className="location-measures"><span>Download<strong>{l.tests?l.download:'—'} <small>Mbps</small></strong></span><span>Latency<strong>{l.tests?l.ping:'—'} <small>ms</small></strong></span></div><small>{vm.data.complaints.filter(c=>c.locationId===l.id&&c.status!=='Resolved').length} unresolved complaints</small></div>)}</div>{!vm.locations.length&&<p className="empty">No areas match your filters.</p>}</>}</>;}



function Analytics({vm}:{vm:CampusVM}){const avg=vm.locations.filter(l=>l.tests).reduce((s,l)=>s+l.download,0)/Math.max(1,vm.locations.filter(l=>l.tests).length);const labels=vm.range==='Today'?['08:00','10:00','12:00','14:00','16:00','18:00']:['Mon','Tue','Wed','Thu','Fri','Sat'];const chart=liveMode?recordedTrend(vm):labels.map((time,i)=>({time,download:Math.round(avg*[.8,1,.62,.75,.92,1.1][i]),upload:Math.round(avg*[.4,.5,.28,.34,.45,.52][i])}));return <div className="analytics-grid"><Panel title="Network performance" subtitle="Recorded throughput for selected buildings" action={<Pick value={vm.range} onChange={vm.setRange} options={['Today','This week']} label="Chart time range"/>}><div className="chart-legend"><span><i className="red"/>Download</span><span><i className="blue"/>Upload</span><small>Mbps · recorded averages</small></div><div className="chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chart} margin={{top:15,right:15,left:-15,bottom:0}}><defs><linearGradient id="downloadFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#ff4051" stopOpacity={.22}/><stop offset="100%" stopColor="#ff4051" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="4 4" vertical={false} stroke="#e9edf2"/><XAxis dataKey="time" axisLine={false} tickLine={false} tick={{fontSize:12,fill:'#718096'}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:12,fill:'#718096'}}/><Tooltip/><Area type="monotone" dataKey="download" name="Download Mbps" stroke="#ff4051" strokeWidth={2.5} fill="url(#downloadFill)"/><Area type="monotone" dataKey="upload" name="Upload Mbps" stroke="#438cf2" strokeWidth={2} fill="transparent"/></AreaChart></ResponsiveContainer></div></Panel><Panel title="Building comparison" subtitle="Average recorded download speed"><div className="building-bars">{vm.locations.map(l=><div key={l.id}><div><strong>{l.building}</strong><span>{l.tests?l.download:'—'} Mbps</span></div><div className="bar-track"><div style={{width:`${Math.min(l.download,100)}%`,background:l.score<50?'#ff4051':l.score<75?'#f5b833':'#17bb6b'}}/></div></div>)}</div>{!vm.locations.length&&<p className="empty">No locations selected.</p>}</Panel></div>;}

function UserManagement({vm}:{vm:CampusVM}){return <Panel title="Campus users" subtitle="Manage staff roles and account status within your campus."><div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Name</TableHead><TableHead>Role</TableHead><TableHead>Account status</TableHead><TableHead className="right">Active</TableHead></TableRow></TableHeader><TableBody>{vm.data.users.map(u=><TableRow key={u.id}><TableCell><div className="user-cell"><span className="avatar light">{u.name.split(' ').map(n=>n[0]).join('')}</span><strong>{u.name}</strong></div></TableCell><TableCell>{u.id===(liveMode?(vm.data as any).user?.id:'admin-demo')?<strong>{u.role}</strong>:<Pick label={`Role for ${u.name}`} value={u.role} onChange={v=>vm.changeUserRole(u.id,v as Role)} options={['Student','IT Support','Manager']}/>}</TableCell><TableCell><Badge text={u.active?'Active':'Inactive'}/></TableCell><TableCell className="right"><Switch aria-label={`Set ${u.name} active`} disabled={u.id===(liveMode?(vm.data as any).user?.id:'admin-demo')} checked={u.active} onCheckedChange={()=>vm.toggleUser(u.id)}/></TableCell></TableRow>)}</TableBody></Table></div></Panel>;}

function SettingsView({vm}:{vm:CampusVM}){const [good,setGood]=useState(vm.data.thresholds.good);const [excellent,setExcellent]=useState(vm.data.thresholds.excellent);return <div className="settings-layout"><Panel title="Network health thresholds" subtitle="Configure campus health bands. Changes are versioned by the server."><form className="form" onSubmit={async e=>{e.preventDefault();vm.setThresholds(good,excellent);}}><label>Good connection starts at<input type="number" min={50} max={99} required value={good} onChange={e=>setGood(Number(e.target.value))}/></label><label>Excellent connection starts at<input type="number" min={51} max={100} required value={excellent} onChange={e=>setExcellent(Number(e.target.value))}/></label><div className="config-notice"><Settings size={18}/><p>New tests use the saved threshold version. Historical scores retain the version used when measured.</p></div><div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Health band</TableHead><TableHead>Score range</TableHead></TableRow></TableHeader><TableBody>{[['Critical','0–24'],['Poor','25–49'],['Fair','50–'+(good-1)],['Good',good+'–'+(excellent-1)],['Excellent',excellent+'–100']].map(([label,range])=><TableRow key={label}><TableCell><Badge text={label}/></TableCell><TableCell>{range}</TableCell></TableRow>)}</TableBody></Table></div>{excellent<=good&&<p role="alert">Excellent must be greater than Good.</p>}<div className="form-actions"><button type="button" className="secondary" onClick={()=>{setGood(75);setExcellent(90);}}>Restore defaults</button><button className="primary" disabled={excellent<=good||good<50||excellent>100}>Save thresholds</button></div></form></Panel><Panel title="Integration checklist"><div className="integration-item"><CircleCheck/><div><strong>Four role dashboards</strong><p>React views and ViewModel actions are ready.</p></div></div><div className="integration-item"><Clock/><div><strong>Authenticated accounts</strong><p>Your role comes from your authenticated campus account.</p></div></div><div className="integration-item"><Clock/><div><strong>Measurement service</strong><p>Browser tests measure the path to the configured campus endpoint.</p></div></div><div className="integration-item"><Clock/><div><strong>Backend repository</strong><p>Campus records are persisted through the authenticated API.</p></div></div></Panel></div>;}

function Notifications({vm}:{vm:CampusVM}){return <Panel title="Updates and notifications" subtitle="Action feedback and complaint updates saved on this device." action={<button className="text-btn" onClick={vm.markAlertsRead} disabled={!vm.unreadAlerts}>{vm.unreadAlerts?'Mark all as read':'All read'}</button>}><div className="activity-feed">{vm.alerts.map(a=><div key={a.id} className={a.readBy.includes(vm.role)?"activity-item read":"activity-item"}><span className={'small-icon '+(a.kind==='error'?'red':a.kind==='success'?'green':'blue')}>{a.kind==='error'?<TriangleAlert size={18}/>:<Bell size={18}/>}</span><div><strong>{a.message}</strong><small>{date(a.createdAt)}</small></div>{!a.readBy.includes(vm.role)&&<span className="unread-dot"/>}</div>)}{!vm.alerts.length&&<p className="empty">No notifications yet. Completed actions and complaint updates will appear here.</p>}</div></Panel>;}









function MaintenanceNotes({vm}:{vm:CampusVM}){const [locationId,setLocationId]=useState(vm.locationId);const [text,setText]=useState('');const notes=(vm.data.maintenanceNotes||[]).filter(n=>n.locationId===locationId);return <Panel title="Maintenance notes" subtitle="Record inspections, repairs, and verification for a campus location."><form className="form" onSubmit={async e=>{e.preventDefault();if(await vm.addMaintenanceNote(locationId,text))setText('');}}><label>Location<Pick label="Maintenance location" value={locationId} onChange={v=>{if(v)setLocationId(v);}} options={vm.data.locations.map(l=>l.id)} optionLabels={Object.fromEntries(vm.data.locations.map(l=>[l.id,l.building+' · '+l.name]))}/></label><label>Maintenance note<textarea aria-label="Maintenance note" required minLength={10} maxLength={1000} value={text} onChange={e=>setText(e.target.value)} placeholder="Describe inspection, repair, and recovery checks…"/></label><small>{text.length}/1000 characters</small><button className="primary" disabled={text.trim().length<10}>Save maintenance note</button></form><div className="section-gap">{notes.map(n=><div className="history-note" key={n.id}><div><strong>{n.author} · {date(n.createdAt)}</strong><p style={{whiteSpace:'pre-wrap'}}>{n.text}</p></div></div>)}{!notes.length&&<p className="empty">No maintenance notes for this location yet.</p>}</div></Panel>;}





function ManagerTools({vm}:{vm:CampusVM}){const model=useManagerViewModel(vm);if(!vm.can('reports'))return <Panel title="Reports access"><p className="empty">Your role does not have reports permission.</p></Panel>;return <>{vm.page==='Reports & Analytics'?<><div className="stats-grid"><Stat title="Saved test results" value={model.tests.length} note="Selected locations" icon={Activity}/><Stat title="Complaints" value={model.complaints.length} note="All statuses" icon={ClipboardList}/><Stat title="Resolved complaints" value={model.complaints.filter(c=>c.status==='Resolved').length} note="Current recorded status" icon={CircleCheck}/><Stat title="Poor locations" value={vm.locations.filter(l=>l.tests&&l.score<50).length} note="Measured scores below 50" icon={TriangleAlert}/></div><Analytics vm={vm}/><div className="section-gap"><Panel title={vm.role==='Administrator'?'System-wide reports':'Manager reports'} subtitle="Export network metrics or complaint and support summaries."><div className="form-actions"><button className="secondary" onClick={vm.exportReport}>Export network report</button><button className="primary" onClick={model.exportSummary}>Export manager summary</button></div></Panel></div></>:vm.page==='Recurring Problems'?<Panel title="Most recurring problems" subtitle="Complaint counts across selected locations, including resolved reports. These are reported symptoms.">{model.problems.length?<><p className="config-notice">Most reported: {model.problems.filter(p=>p.count===model.problems[0].count).map(p=>p.category).join(', ')} · {model.problems[0].count} report(s) each</p><div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Problem</TableHead><TableHead>Reports</TableHead><TableHead>Recurrence</TableHead></TableRow></TableHeader><TableBody>{model.problems.map(p=><TableRow key={p.category}><TableCell><div className="issue-cell"><span className="small-icon amber"><Wifi size={17}/></span><strong>{p.category}</strong></div></TableCell><TableCell>{p.count}</TableCell><TableCell><Badge text={p.count>=2?'Repeated reports':'Single report'}/></TableCell></TableRow>)}</TableBody></Table></div></>:<p className="empty">No complaints in the selected locations.</p>}</Panel>:<><Panel title="IT support workload" subtitle="Current assignments, resolutions, and recorded maintenance notes."><div className="table-scroll"><Table><TableHeader><TableRow>{['Staff','Active assignments','Resolved','Maintenance notes'].map(s=><TableHead key={s}>{s}</TableHead>)}</TableRow></TableHeader><TableBody>{model.staff.map(s=><TableRow key={s.name}><TableCell><div className="user-cell"><span className="avatar light">{s.name.split(' ').map(n=>n[0]).join('')}</span><strong>{s.name}</strong></div></TableCell><TableCell>{s.assigned}</TableCell><TableCell>{s.resolved}</TableCell><TableCell>{s.notes}</TableCell></TableRow>)}</TableBody></Table></div></Panel><div className="section-gap"><Panel title="Support activity timeline" subtitle="Timestamped complaint updates and maintenance notes recorded in this app.">{model.events.map(e=><div className="history-note" key={e.id}><div><strong>{e.author} · {date(e.createdAt)}</strong><small>{vm.data.locations.find(l=>l.id===e.locationId)?.name}</small><p style={{whiteSpace:'pre-wrap'}}>{e.text}</p></div></div>)}{!model.events.length&&<p className="empty">No recorded activity yet. New IT updates and maintenance notes will appear here.</p>}</Panel></div></>}</>; }



function PermissionSettings({vm}:{vm:CampusVM}){const [target,setTarget]=useState<Role>('IT Support');const [draft,setDraft]=useState<Permission[]>(vm.data.permissions?.['IT Support']||defaultPermissions['IT Support']);return <Panel title="Role permissions" subtitle="Configure campus-wide IT Support and Manager capabilities."><div className="form"><Pick label="Permission role" value={target} options={['IT Support','Manager']} onChange={v=>{const r=v as Role;setTarget(r);setDraft(vm.data.permissions?.[r]||defaultPermissions[r]);}}/><div className="table-scroll"><Table><TableHeader><TableRow><TableHead>Capability</TableHead><TableHead>Allowed</TableHead></TableRow></TableHeader><TableBody>{Object.entries(permissionLabels).filter(([key])=>target==='IT Support'?['tests','complaints','maintenance'].includes(key):key==='reports').map(([key,label])=><TableRow key={key}><TableCell><strong>{label}</strong></TableCell><TableCell><Switch aria-label={label} checked={draft.includes(key as Permission)} onCheckedChange={enabled=>setDraft(d=>enabled?[...d,key as Permission]:d.filter(p=>p!==key))}/></TableCell></TableRow>)}</TableBody></Table></div><button className="primary" onClick={()=>vm.savePermissions(target,draft)}>Save permissions</button><div className="config-notice"><ShieldCheck size={18}/><p>Permissions are enforced by the server. The administrator account remains protected.</p></div></div></Panel>;}



